#include "native/providers/gdn/sm121_bf16_fma.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>
namespace fma=qrt_sm121_bf16_fma;
template<class T>std::vector<T> read(const char* path,size_t count){
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if(!f||f.tellg()!=std::streamoff(count*sizeof(T)))throw std::runtime_error("input extent");
    std::vector<T> r(count);f.seekg(0);f.read(reinterpret_cast<char*>(r.data()),count*sizeof(T));
    if(!f)throw std::runtime_error("input read");return r;
}
uint16_t bf16(float f){uint32_t b;std::memcpy(&b,&f,4);return uint16_t((b+0x7fff+((b>>16)&1))>>16);}
int main(int argc,char** argv)try{
    if(argc!=8)throw std::runtime_error("norm rope_cache heads first_position rows mode output");
    const unsigned heads=std::stoul(argv[3]),first=std::stoul(argv[4]),rows=std::stoul(argv[5]),mode=std::stoul(argv[6]);
    if((heads!=2&&heads!=16)||!rows||rows>8192||first>131072||rows>139264-first||mode>1)throw std::runtime_error("shape");
    auto values=read<uint16_t>(argv[1],size_t(rows)*heads*256);
    const auto cache=read<uint16_t>(argv[2],264736u*64u);
    if(std::filesystem::exists(argv[7]))throw std::runtime_error("output exists");
    size_t differences=0;
    for(unsigned row=0;row<rows;++row)for(unsigned head=0;head<heads;++head)for(unsigned pair=0;pair<32;++pair){
        const size_t base=(size_t(row)*heads+head)*256;
        const uint16_t a=values[base+pair],b=values[base+pair+32];
        const uint16_t c=cache[size_t(first+row)*64+pair],s=cache[size_t(first+row)*64+pair+32];
        const uint16_t bs=bf16(fma::widen(b)*fma::widen(s)),as=bf16(fma::widen(a)*fma::widen(s));
        const uint16_t old_a=bf16(fmaf(fma::widen(a),fma::widen(c),-fma::widen(bs)));
        const uint16_t old_b=bf16(fmaf(fma::widen(b),fma::widen(c),fma::widen(as)));
        const uint16_t new_a=fma::round(a,c,bs^0x8000),new_b=fma::round(b,c,as);
        differences+=(old_a!=new_a)+(old_b!=new_b);
        values[base+pair]=mode?new_a:old_a;values[base+pair+32]=mode?new_b:old_b;
    }
    std::ofstream out(argv[7],std::ios::binary);out.write(reinterpret_cast<char*>(values.data()),values.size()*2);
    out.close();if(!out)throw std::runtime_error("write");
    std::cout<<"{\"elements\":"<<values.size()<<",\"single_round_changes\":"<<differences<<",\"mode\":"<<mode<<"}\n";
    return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}
